#include <iostream>
using namespace std;
const int ARRAY_SIZE = 6;
void bubbleSort(int arr[]) {
    int i, j, temp;
    for (i = 0; i < ARRAY_SIZE - 1; i++) {
        for (j = 0; j < ARRAY_SIZE - i - 1; j++) {
            if (arr[j] > arr[j+1]) {
                temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}
