    res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Total-Count');
    res.setHeader('Access-Control-Allow-Headers', 'X-Requested-With, X-Total-Count, Content-Type, Accept, Authorization');

    next();
  };
};
```

