function determineProtocol(inputData) {
  let protocol;

  if (inputData.protocol === undefined) { // Add this check to handle cases where protocol is not provided in inputData
    if (inputData.sourceIP && inputData.destinationIP && /^(([0-9a-f]{1,4}:){7}[0-9a-f]{1,4})$/.test(inputData.sourceIP) && /^(([0-9a-f]{1,4}:){7}[0-9a-f]{1,4})$/.test(inputData.destinationIP)) { // Check for valid IPv6 format
