```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"io/ioutil"
	"os"
	"reflect"

	"github.com/apache/avro/avro"
	"github.com/apache/avro/reflect"
)

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run main.go <source_file> <struct_name>")
		return
	}

	filePath := os.Args[1]
	structName := os.Args[2]

	fset := token.NewFileSet()
	node, err := parser.ParseFile(fset, filePath, nil, parser.ParseComments)
	if err != nil {
		panic(err)
	}

	var structType reflect.Type
	for _, decl := range node.Types.List {
		if decl.Name == structName {
			structType = decl.Obj.(*ast.StructType)
			break
		}
	}

	if structType == nil {
		fmt.Printf("Error: No such struct %s in file %s\n", structName, filePath)
		return
	}

	schemaBuilder := avro.NewGenericSchemaBuilder()
	generatedSchema, err := buildAvroSchema(structType, schemaBuilder)
	if err != nil {
		fmt.Println("Error while generating Avro schema:", err)
		return
	}

	avroJSONSchema, err := json.MarshalIndent(generatedSchema, "", "  ")
	if err != nil {
		fmt.Println("Error while encoding Avro schema to JSON:", err)
		return
	}

