 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebAPI project, you'll first need to verify the token and then extract the claims containing the username information. Here's a step-by-step guide:

1. Install the `Microsoft.IdentityModel.Tokens` NuGet package for handling JWT validation.

```sh
Install-Package Microsoft.IdentityModel.Tokens
```

2. Create a method for validating and extracting the username from the JWT token.

```csharp
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public string GetUsernameFromToken(string token)
{
    try
    {
        // Handling the JWT token
        JwtSecurityTokenHandler tokenHandler = new JwtSecurityTokenHandler();
        JwtSecurityToken jwtToken = tokenHandler.ReadJwtToken(token);

        // Extracting user identity from the token
        ClaimsPrincipal principal = jwtToken.Principal;
        ClaimsIdentity identity = (ClaimsIdentity)principal;
        Claim usernameClaim = identity.FindFirst("sub"); // "sub" is the standard claim type for the subject (username)

        if (usernameClaim != null)
            return usernameClaim.Value;
        else
            throw new Exception("Could not find the 'sub' claim.");
    }
    catch (Exception ex)
    {
        throw new Exception("Invalid token provided.", ex);
    }
}
```

3. Use this method in your API controller action or wherever required.

```csharp
[HttpGet]
public IActionResult GetUserData([FromHeader(Name = "Authorization")] string authorizationHeader)
{
    try
    {
        string token = authorizationHeader.Replace("Bearer ", ""); // Remove the Bearer prefix
        string username = GetUsernameFromToken(token);
        // Process the request based on the retrieved username
        return Ok();
    }
    catch (Exception ex)
    {
        return BadRequest($"Error: {ex.Message}");
    }
}
```

