 To design an efficient NoSQL document schema for a hotel room reservation system on MongoDB with the given constraints, I'd suggest the following schema:

```javascript
// Define the Hotel model
const HotelSchema = new mongoose.Schema({
  name: { type: String, required: true },
  location: { type: { type: String, default: '' }, coordinates: { type: [Number], default: [] } }, // Add more fields if needed
  rooms: [{ type: Schema.Types.ObjectId, ref: 'Room' }], // Array of Room IDs
  createdAt: { type: Date, default: Date.now },
});

// Define the Room model
const RoomSchema = new mongoose.Schema({
  number: { type: Number, required: true, unique: true },
  type: { type: String, enum: ['single', 'double', 'suite'], required: true },
  capacity: { type: Number, min: 1, max: 4 }, // Adjust the range as needed
  pricePerNight: { type: Number, required: true },
  availability: { // Use an array of objects or a map to store availability for each day
    [Date.parse('YYYY-MM-DD')]: { occupied: Boolean, reservationId: ObjectId },
  },
  createdAt: { type: Date, default: Date.now },
});

// Create a reservation index for the reservationId field in the availability object
RoomSchema.index({ 'availability.reservationId': 1 });

// Combine the two schemas into one document (Hotel with embedded Rooms)
const HotelWithRoomsSchema = new mongoose.Schema({
  name: { type: String, required: true },
  location: { type: { type: String, default: '' }, coordinates: { type: [Number], default: [] } },
  rooms: [RoomSchema],
  createdAt: { type: Date, default: Date.now },
});

module.exports = mongoose.model('HotelWithRooms', HotelWithRoomsSchema);
```

