xhr.open('GET', 'https://example.com/api/endpoint');
xhr.onreadystatechange = function() {
  if (this.readyState === XMLHttpRequest.HEADERS_RECEIVED) {
    console.log(this.getResponseHeader("Access-Control-Allow-Origin"));
    console.log(this.getResponseHeader("Access-Control-Allow-Credentials"));
  }
};
xhr.send();
```

Or using Fetch API:

```javascript
fetch('https://example.com/api/endpoint')
