 Here's the `redis.js` file with the required `RedisClient` class and an exported instance named `redisClient`. Make sure you have installed the `redis` package using `npm install redis` before running the code.

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error(`Error connecting to Redis: ${err}`));
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) return reject(err);
        resolve(reply);
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, result) => {
        if (err) return reject(err);
        resolve(result);
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = { RedisClient, redisClient };
```

