checkMNPStatusAPI(index, phoneNo) {
  const updatedRegistrations = [...this.state.registrations]; // create a copy of registrations
  fetch(api.checkPortInStatus(user.getProductCode(), phoneNo), {
    headers: { Authorization: "Bearer " + user.getAccessToken() },
    method: "GET"
